<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\ProfileExaminationOpeningService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:open-profile-examination',description:'Open a secured Profile examination case and commission the canonical panel')]
final class SenateOpenProfileExaminationCommand extends Command{public function __construct(private readonly ProfileExaminationOpeningService$s){parent::__construct();}protected function configure():void{$this->addArgument('admission-id',InputArgument::REQUIRED)->addArgument('lord-speaker-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->open((string)$i->getArgument('admission-id'),(string)$i->getArgument('lord-speaker-binding-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if($i->getOption('json'))$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));else$o->writeln('<info>PROFILE_EXAMINATION_OPENED</info> '.$r['case']['case_id']);return self::SUCCESS;}}
